const TOTAL_LABEL: Record<Range, string> = {
  today: 'tracked today',
  week: 'tracked this week',
};

function isRange(value: unknown): value is Range {
  const isToday = value === 'today';
  const isWeek = value === 'week';
  return isToday || isWeek;
}

function totalOf(entries: WorkEntry[]) {
  let total = 0;
  for (const entry of entries) {
    total += entry.minutes;
  }
  return total;
}

function longestOf(entries: WorkEntry[]) {
  const minutes = entries.map((entry) => entry.minutes);
  return Math.max(1, ...minutes);
}

function presenceOf(personId: string): Presence {
  return PRESENCE[personId] ?? 'away';
}

function PresenceAvatar({
  person,
  presence,
}: {
  person: Person;
  presence: Presence;
}) {
  const isTracking = presence === 'tracking';
  const isPaused = presence === 'paused';

  return (
    <span className='relative inline-flex shrink-0'>
      <PersonAvatar person={person} className='size-8 text-xs' />
      {isTracking && (
        <span className='bg-card text-success-foreground ring-card absolute -end-0.5 -bottom-0.5 flex size-3.5 items-center justify-center rounded-full ring-2'>
          <PlayIcon strokeWidth={2.5} className='size-2' />
        </span>
      )}
      {isPaused && (
        <span className='bg-card text-warning-foreground ring-card absolute -end-0.5 -bottom-0.5 flex size-3.5 items-center justify-center rounded-full ring-2'>
          <PauseIcon strokeWidth={2.5} className='size-2' />
        </span>
      )}
    </span>
  );
}

function layoutOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return false;
  }
  return 'position';
}

function WorkRow({ entry, longest }: { entry: WorkEntry; longest: number }) {
  const shouldReduceMotion = useReducedMotion();
  const person = personOf(entry.personId);
  const presence = presenceOf(entry.personId);
  const share = entry.minutes / longest;
  const barStyle = { transform: `scaleX(${share})` } as React.CSSProperties;

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      layout={layoutOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='flex items-center gap-3 py-2'>
        <PresenceAvatar person={person} presence={presence} />
        <div className='min-w-0 flex-1'>
          <p className='truncate text-[13px] font-medium'>
            {person.name}
            <span className='sr-only'>, {PRESENCE_LABEL[presence]}</span>
          </p>
          <p className='text-muted-foreground truncate text-xs'>
            <span className='tabular-nums'>{entry.taskKey}</span>{' '}
            {entry.taskTitle} · {relativeTimeOf(entry.lastAt)}
          </p>
        </div>
        <div className='flex w-20 shrink-0 flex-col items-end gap-1.5'>
          <RollingCount
            value={entry.minutes}
            format={durationLabelOf}
            className='text-[13px] font-medium'
          />
          <span
            aria-hidden='true'
            className='bg-foreground/[0.06] block h-1 w-full overflow-hidden rounded-full'
          >
            <span
              style={barStyle}
              className='bg-primary block h-full w-full origin-left rounded-full transition-transform duration-300 ease-(--ease-out-strong)'
            />
          </span>
        </div>
      </div>
    </motion.li>
  );
}

function rowKeyOf(entry: WorkEntry) {
  return `${entry.personId}-${entry.taskKey}`;
}

export default function Activity04() {
  const [range, setRange] = useState<Range>('today');
  const entries = ENTRIES[range];
  const total = totalOf(entries);
  const longest = longestOf(entries);

  function change(value: unknown) {
    if (isRange(value)) {
      setRange(value);
    }
  }

  return (
    <section aria-label='Team activity' className='w-full max-w-md'>
      <header className='flex flex-wrap items-start justify-between gap-3'>
        <div>
          <h3 className='text-sm font-medium'>Team activity</h3>
          <p className='text-muted-foreground mt-0.5 text-xs'>
            <RollingCount
              value={total}
              format={durationLabelOf}
              className='text-foreground font-medium'
            />{' '}
            {TOTAL_LABEL[range]}
          </p>
        </div>
        <Tabs value={range} onValueChange={change}>
          <TabsList variant='segmented' aria-label='Range'>
            <TabsTab value='today'>Today</TabsTab>
            <TabsTab value='week'>This week</TabsTab>
          </TabsList>
        </Tabs>
      </header>
      <ul className='mt-2'>
        <AnimatePresence initial={false}>
          {entries.map((entry) => (
            <WorkRow key={rowKeyOf(entry)} entry={entry} longest={longest} />
          ))}
        </AnimatePresence>
      </ul>
    </section>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Person } from './people';

export type StatusId =
  'backlog' | 'todo' | 'in_progress' | 'in_review' | 'done';

export type PriorityId = 'urgent' | 'high' | 'medium' | 'low';

export const STATUS_NAME: Record<StatusId, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
};

const STATUS_COLOR: Record<StatusId, string> = {
  backlog: 'var(--muted-foreground)',
  todo: 'var(--muted-foreground)',
  in_progress: 'var(--warning)',
  in_review: 'var(--primary)',
  done: 'var(--success)',
};

export const PRIORITY_NAME: Record<PriorityId, string> = {
  urgent: 'Urgent',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
};

const PIE_RADIUS = 2;

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function StartedShape({ share }: { share: number }) {
  const filled = share * PIE_CIRCUMFERENCE;
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={`${filled} ${PIE_CIRCUMFERENCE}`}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const glyphStyle = { color: STATUS_COLOR[status] } as React.CSSProperties;
  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
    >
      {statusShapeOf(status)}
    </svg>
  );
}

const BAR_HEIGHTS = [4, 7, 10];

const FILLED_BARS: Record<PriorityId, number> = {
  urgent: 3,
  high: 3,
  medium: 2,
  low: 1,
};

function barOpacityOf(index: number, filledCount: number) {
  if (index < filledCount) {
    return 0.8;
  }
  return 0.2;
}

export function PriorityGlyph({
  priority,
  className,
}: {
  priority: PriorityId;
  className?: string;
}) {
  const isUrgent = priority === 'urgent';
  const filledCount = FILLED_BARS[priority];
  return (
    <svg
      viewBox='0 0 14 14'
      aria-hidden='true'
      className={cn(
        'text-foreground size-3.5 shrink-0',
        isUrgent && 'text-destructive-ink',
        className
      )}
    >
      {BAR_HEIGHTS.map((height, index) => (
        <rect
          key={height}
          x={1.5 + index * 4.25}
          y={12 - height}
          width='2.5'
          height={height}
          rx='0.75'
          fill='currentColor'
          fillOpacity={barOpacityOf(index, filledCount)}
        />
      ))}
    </svg>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-6 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

